import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("Equal")
        return

    nums = list(map(int, data))

    if nums[0] == -1:
        print("Equal")
        return

    n = nums[0]
    numbers = nums[1:1+n]

    odd_sum = 0
    even_sum = 0

    for num in numbers:
        if num % 2 == 0:
            even_sum += num
        else:
            odd_sum += num

    if odd_sum > even_sum:
        print("Odd Sum Greater")
    elif even_sum > odd_sum:
        print("Even Sum Greater")
    else:
        print("Equal")

if __name__ == "__main__":
    main()
